	private interface Call { Object invoke(String method, Object[] args); }
	@SuppressWarnings("unchecked")
	private static <T> T proxy(Class<T> type, Call call)
	{
		return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (object, method, args) ->
		{
			if (method.getName().equals("equals")) { return object == args[0]; }
			if (method.getName().equals("hashCode")) { return System.identityHashCode(object); }
			Object value = call.invoke(method.getName(), args == null ? new Object[0] : args);
			if (method.getReturnType() == void.class) { return null; }
			if (value != null) { return value; }
			if (method.getReturnType() == boolean.class) { return false; }
			if (method.getReturnType() == int.class) { return 0; }
			if (method.getReturnType() == long.class) { return 0L; }
			return null;
		});
	}

	private static final class Surface
	{
		final W root = new W(null);
		final W frame;
		final W title;
		final Client client;
		Point mouse = new Point(0, 0);
		long press;
		final List<Integer> sounds = new ArrayList<>();
		Surface()
		{
			root.api.setOriginalX(20).setOriginalY(30).setOriginalWidth(480).setOriginalHeight(300);
			frame = root.create(0, WidgetType.LAYER);
			frame.api.setOriginalWidth(480).setOriginalHeight(300);
			title = frame.create(0, WidgetType.TEXT);
			title.api.setText("Configure World Switcher").setOriginalWidth(480).setOriginalHeight(32);
			client = proxy(Client.class, (method, args) ->
			{
				if (method.equals("playSoundEffect")) { sounds.add((int) args[0]); }
				if (method.equals("getWidget")) { return (int) args[0] == InterfaceID.WorldswitcherOptions.FRAME ? frame.api : root.api; }
				if (method.equals("getCanvasWidth")) { return 1000; }
				if (method.equals("getCanvasHeight")) { return 800; }
				if (method.equals("getItemCount")) { return 40000; }
				if (method.equals("getMouseCanvasPosition")) { return mouse; }
				if (method.equals("getMouseLastPressedMillis")) { return press; }
				return null;
			});
		}
	}

	private static final class W
	{
		final Widget api;
		final W parent;
		final Map<String, Object> props = new HashMap<>();
		final Map<Integer, String> actions = new HashMap<>();
		Widget[] children = new Widget[0];
		final List<W> created = new ArrayList<>();
		int index;
		W(W parent)
		{
			this.parent = parent;
			api = proxy(Widget.class, this::call);
		}
		W create(int index, int type)
		{
			if (index < 0) { index = children.length; }
			if (index >= children.length) { children = Arrays.copyOf(children, index + 1); }
			W child = new W(this); child.index = index; child.props.put("Type", type);
			children[index] = child.api; created.add(child); return child;
		}
		List<W> live()
		{
			List<W> result = new ArrayList<>();
			for (W child : created) { if (child.index < children.length && children[child.index] == child.api) { result.add(child); } }
			return result;
		}
		void op(int op) { listener("OnOpListener", op, 0); }
		void wheel(int delta) { listener("OnScrollWheelListener", 0, delta); }
		void listener(String name, int op, int delta)
		{
			Object[] args = (Object[]) props.get(name);
			((JavaScriptCallback) args[0]).run(proxy(ScriptEvent.class, (method, values) -> method.equals("getOp") ? op : method.equals("getMouseY") ? delta : null));
		}
		private Object call(String method, Object[] args)
		{
			if (method.equals("createChild")) { return create((int) args[0], (int) args[1]).api; }
			if (method.equals("getChildren")) { return children; }
			if (method.equals("getDynamicChildren")) { return Arrays.stream(children).filter(Objects::nonNull).toArray(Widget[]::new); }
			if (method.equals("getChild")) { int i = (int) args[0]; return i < children.length ? children[i] : null; }
			if (method.equals("getIndex")) { return index; }
			if (method.equals("setAction")) { actions.put((int) args[0], (String) args[1]); return api; }
			if (method.startsWith("set") && args.length == 1) { props.put(method.substring(3), args[0]); return api; }
			if (method.equals("getWidth")) { return props.get("OriginalWidth"); }
			if (method.equals("getHeight")) { return props.get("OriginalHeight"); }
			if (method.equals("getText")) { return props.getOrDefault("Text", ""); }
			if (method.equals("getCanvasLocation"))
			{
				Point origin = parent == null ? new Point(0, 0) : parent.api.getCanvasLocation();
				return new Point(origin.getX() + (int) props.getOrDefault("OriginalX", 0), origin.getY() + (int) props.getOrDefault("OriginalY", 0));
			}
			if (method.equals("getBounds")) { Point p = api.getCanvasLocation(); return new Rectangle(p.getX(), p.getY(), api.getWidth(), api.getHeight()); }
			if (method.equals("contains")) { Point p = (Point) args[0]; return api.getBounds().contains(p.getX(), p.getY()); }
			if (method.equals("getFont")) { return proxy(FontTypeFace.class, (m, a) -> m.equals("getTextWidth") ? ((String) a[0]).length() * 6 : null); }
			if (method.startsWith("get")) { return props.get(method.substring(3)); }
			return null;
		}
	}
}

package com.kierenboal.worldfilterpresets;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.events.ScriptPreFired;
import org.junit.Test;
import static org.junit.Assert.*;

public class PresetInGamePreviewTest
{
	@Test
	public void previewDoesNotSubstitutePresetFiltersAndUpdateUsesNativeValues() throws Exception
	{
		Map<Integer, Integer> masks = new HashMap<>();
		masks.put(14967, 3); masks.put(14968, 12); masks.put(14969, 7);
		Map<Integer, Object> varcs = new HashMap<>();
		varcs.put(1157, 65);
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(object, method, args) ->
			{
				switch (method.getName())
				{
					case "getVarbitValue": return masks.getOrDefault((int) args[0], 0);
					case "setVarbit": masks.put((int) args[0], (int) args[1]); return null;
					case "getVarcIntValue": return varcs.getOrDefault((int) args[0], 0);
					case "getVarcMap": return varcs;
					default: return null;
				}
			});
		WorldFilterPresetsPlugin plugin = new WorldFilterPresetsPlugin();
		PresetRepository repository = new PresetRepository(PresetTestSupport.codec(), null, ignored -> { });
		Preset preset = repository.add("A", new int[11]);
		set(plugin, "client", client); set(plugin, "repository", repository);
		set(plugin, "running", true); set(plugin, "supported", true);
		set(plugin, "previewingInGameFilters", true);
		set(plugin, "previewTicket", 3L);
		ScriptPreFired script = new ScriptPreFired(892);
		plugin.onScriptPreFired(script);
		assertEquals(Integer.valueOf(12), masks.get(14968));
		assertEquals(65, varcs.get(1157));
		assertArrayEquals(new int[11], repository.find(preset.id).filters());
		Method end = WorldFilterPresetsPlugin.class.getDeclaredMethod("endInGamePreview", long.class);
		end.setAccessible(true); end.invoke(plugin, 2L);
		assertTrue((boolean) get(plugin, "previewingInGameFilters"));
		end.invoke(plugin, 3L);
		assertFalse((boolean) get(plugin, "previewingInGameFilters"));
		assertArrayEquals(new int[11], repository.find(preset.id).filters());
		Method update = WorldFilterPresetsPlugin.class.getDeclaredMethod("updateFromInGame", String.class);
		update.setAccessible(true); update.invoke(plugin, preset.id);
		int[] expected = {3, 12, 7, 65, 0, 0, 0, 0, 0, 0, 0};
		assertArrayEquals(expected, repository.find(preset.id).filters());
		assertArrayEquals(expected, repository.working());
		assertFalse(repository.dirty());
	}

	private static void set(Object target, String name, Object value) throws Exception
	{
		Field field = target.getClass().getDeclaredField(name); field.setAccessible(true); field.set(target, value);
	}
	private static Object get(Object target, String name) throws Exception
	{
		Field field = target.getClass().getDeclaredField(name); field.setAccessible(true); return field.get(target);
	}
}

package com.kierenboal.worldfilterpresets;

import org.junit.Test;
import static org.junit.Assert.*;

public class PresetLabelMarqueeTest
{
	@Test
	public void startsEllipsizedAndScrollsOnlyAfterThreeSeconds()
	{
		PresetLabelMarquee label = new PresetLabelMarquee();
		assertEquals("AB...", label.text("ABCDEFGHIJ", 5, String::length, 100));
		assertEquals("AB...", label.text("ABCDEFGHIJ", 5, String::length, 3099));
		assertEquals("BC...", label.text("ABCDEFGHIJ", 5, String::length, 3100));
		assertEquals("CD...", label.text("ABCDEFGHIJ", 5, String::length, 3280));
		assertEquals("FGHIJ", label.text("ABCDEFGHIJ", 5, String::length, 3820));
		assertEquals("FGHIJ", label.text("ABCDEFGHIJ", 5, String::length, 6500));
		assertEquals("AB...", label.text("ABCDEFGHIJ", 5, String::length, 7000));
	}

	@Test
	public void selectingOrResizingRestartsTheDelayAndShortNamesStayStill()
	{
		PresetLabelMarquee label = new PresetLabelMarquee();
		label.text("ABCDEFGHIJ", 5, String::length, 0);
		assertEquals("FGHIJ", label.text("ABCDEFGHIJ", 5, String::length, 4000));
		assertEquals("12...", label.text("1234567890", 5, String::length, 4001));
		assertEquals("123...", label.text("1234567890", 6, String::length, 8000));
		assertEquals("123...", label.text("1234567890", 6, String::length, 10999));
		assertEquals("Short", label.text("Short", 6, String::length, 11000));
		assertEquals("Short", label.text("Short", 6, String::length, 50000));
	}

	@Test
	public void measuresPixelWidthsAndAlwaysKeepsTheVisibleTextWithinItsSpace()
	{
		PresetLabelMarquee label = new PresetLabelMarquee();
		for (long time = 0; time < 12000; time += 40)
		{
			String text = label.text("WWWWiiiiMMMM", 30, value -> value.chars().map(c -> c == 'i' ? 2 : 6).sum(), time);
			assertTrue(text.chars().map(c -> c == 'i' ? 2 : 6).sum() <= 30);
		}
	}

	@Test
	public void escapesMarkupAndDoesNotSplitUnicodeCharacters()
	{
		PresetLabelMarquee label = new PresetLabelMarquee();
		assertEquals("<lt>name<gt>", label.text("<name>", 50, String::length, 0));
		for (int time = 0; time < 10000; time += 180)
		{
			String text = label.text("A\uD83D\uDE00BCDEFGHIJ", 5, String::length, time);
			for (int i = 0; i < text.length(); i++)
			{
				if (Character.isHighSurrogate(text.charAt(i))) { assertTrue(Character.isLowSurrogate(text.charAt(++i))); }
				else { assertFalse(Character.isLowSurrogate(text.charAt(i))); }
			}
		}
	}
}

package com.kierenboal.worldfilterpresets;

import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.ScriptEvent;
import net.runelite.api.ScriptEventBuilder;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.widgets.Widget;
import org.junit.Test;
import static org.junit.Assert.*;

public class PresetListenerTest
{
	private static final int[] MASKS = {14967, 14968, 14969};
	private static final int[] SEARCH = {1157, 1158, 1159, 1160, 1161, 212, 1162, 1163};
	private final WorldFilterPresetsPlugin plugin = new WorldFilterPresetsPlugin();
	private final Map<Integer, Integer> masks = new HashMap<>();
	private final Map<Integer, Object> search = new HashMap<>();
	private final Widget widget = proxy(Widget.class, (object, method, args) -> null);
	private final Object[] arguments = {891, 123};
	private Widget source;
	private int operation = -1;
	private int executions;

	@Test
	public void refreshPreservesContextAndUsesDefaultScriptRestrictions() throws Exception
	{
		setup(() -> { });
		runListener(0);
		assertSame(widget, source);
		assertEquals(0, operation);
		assertEquals(1, executions);
	}

	@Test
	public void successfulScriptRestoresNativeFiltersAndSearch() throws Exception
	{
		verifyScopeRestored(false);
	}

	@Test
	public void failingScriptRestoresNativeFiltersAndSearch() throws Exception
	{
		verifyScopeRestored(true);
	}

	private void verifyScopeRestored(boolean fail) throws Exception
	{
		RuntimeException failure = new IllegalStateException("Script execution failed");
		setup(() ->
		{
			plugin.onScriptPreFired(new ScriptPreFired(892));
			for (int mask : MASKS) { assertEquals(Integer.valueOf(0), masks.get(mask)); }
			for (int varc : SEARCH) { assertEquals(0, search.get(varc)); }
			if (fail) { throw failure; }
			plugin.onScriptPostFired(new ScriptPostFired(892));
		});
		Map<Integer, Integer> nativeMasks = new HashMap<>(masks);
		Map<Integer, Object> nativeSearch = new HashMap<>(search);
		try
		{
			runListener(1);
			assertFalse("Expected the script failure to propagate", fail);
		}
		catch (InvocationTargetException ex)
		{
			assertTrue(fail);
			assertSame(failure, ex.getCause());
		}
		assertSame(widget, source);
		assertEquals(1, operation);
		assertEquals(1, executions);
		assertEquals(nativeMasks, masks);
		assertEquals(nativeSearch, search);
		assertEquals(-1, get("scopedScript"));
		assertTrue(((Map<?, ?>) get("originalSearch")).isEmpty());
	}

	private void setup(Runnable execute) throws Exception
	{
		masks.put(14967, 3); masks.put(14968, 12); masks.put(14969, 7);
		search.put(1157, 5);
		search.put(212, -1); // Preserve raw values and absent entries, not just normalized filters.
		ScriptEvent event = proxy(ScriptEvent.class, (object, method, args) ->
		{
			if (method.getName().equals("run")) { executions++; execute.run(); return null; }
			throw new AssertionError("Unexpected script event call: " + method.getName());
		});
		ScriptEventBuilder builder = proxy(ScriptEventBuilder.class, (object, method, args) ->
		{
			switch (method.getName())
			{
				case "setSource": source = (Widget) args[0]; return object;
				case "setOp": operation = (int) args[0]; return object;
				case "build": return event;
				default: throw new AssertionError("Unexpected script builder call: " + method.getName());
			}
		});
		Client client = proxy(Client.class, (object, method, args) ->
		{
			switch (method.getName())
			{
				case "createScriptEventBuilder": assertSame(arguments, args[0]); return builder;
				case "getVarbitValue": return masks.getOrDefault((int) args[0], 0);
				case "setVarbit": masks.put((int) args[0], (int) args[1]); return null;
				case "getVarcIntValue": return search.getOrDefault((int) args[0], 0);
				case "getVarcMap": return search;
				default: throw new AssertionError("Unexpected client call: " + method.getName());
			}
		});
		PresetRepository repository = new PresetRepository(PresetTestSupport.codec(), null, ignored -> { });
		repository.add("Preset", new int[11]);
		set("client", client); set("repository", repository);
		set("running", true); set("supported", true);
	}

	private void runListener(int op) throws Exception
	{
		Method method = plugin.getClass().getDeclaredMethod("runListener", Widget.class, Object[].class, int.class);
		method.setAccessible(true);
		method.invoke(plugin, widget, arguments, op);
	}

	private void set(String name, Object value) throws Exception
	{
		Field field = plugin.getClass().getDeclaredField(name);
		field.setAccessible(true); field.set(plugin, value);
	}

	private Object get(String name) throws Exception
	{
		Field field = plugin.getClass().getDeclaredField(name);
		field.setAccessible(true); return field.get(plugin);
	}

	private static <T> T proxy(Class<T> type, java.lang.reflect.InvocationHandler handler)
	{
		return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, handler));
	}
}

package com.kierenboal.worldfilterpresets;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BooleanSupplier;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import org.junit.Test;
import static org.junit.Assert.*;

public class PresetMessageTest
{
	private GameState gameState = GameState.STARTING;
	private Player player;
	private final List<String> messages = new ArrayList<>();
	private final DeferredThread thread = new DeferredThread();
	private final WorldFilterPresetsPlugin plugin = new WorldFilterPresetsPlugin();

	private void setup() throws Exception
	{
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (object, method, args) ->
		{
			if (method.getName().equals("getGameState")) { return gameState; }
			if (method.getName().equals("getLocalPlayer")) { return player; }
			if (method.getName().equals("addChatMessage"))
			{
				assertEquals(GameState.LOGGED_IN, gameState);
				assertNotNull(player);
				messages.add((String) args[2]);
			}
			return null;
		});
		set("client", client); set("clientThread", thread); set("running", true);
	}

	private void set(String name, Object value) throws Exception
	{
		Field field = plugin.getClass().getDeclaredField(name); field.setAccessible(true); field.set(plugin, value);
	}
	private void message(String value, boolean red) throws Exception
	{
		Method method = plugin.getClass().getDeclaredMethod("message", String.class, boolean.class);
		method.setAccessible(true); method.invoke(plugin, value, red);
	}
	private void ready()
	{
		gameState = GameState.LOGGED_IN;
		player = (Player) Proxy.newProxyInstance(Player.class.getClassLoader(), new Class<?>[]{Player.class}, (object, method, args) -> null);
	}

	@Test
	public void startupWarningWaitsForLoginAndPlayerAndDeliversOnce() throws Exception
	{
		setup(); message("Unable to load saved presets: duplicate names", false);
		thread.tick(); assertTrue(messages.isEmpty());
		GameStateChanged event = new GameStateChanged(); event.setGameState(GameState.LOGIN_SCREEN);
		plugin.onGameStateChanged(event);
		gameState = GameState.LOGIN_SCREEN;
		thread.tick(); assertTrue(messages.isEmpty());
		gameState = GameState.LOGGED_IN;
		thread.tick(); assertTrue(messages.isEmpty()); // Local player can still be null during login.
		ready(); thread.tick(); thread.tick();
		assertEquals(1, messages.size());
		assertEquals("World Filter Presets: Unable to load saved presets: duplicate names", messages.get(0));
	}

	@Test
	public void profileResetAndShutdownDiscardPendingMessages() throws Exception
	{
		setup(); message("Old profile", false);
		Method reset = plugin.getClass().getDeclaredMethod("reset"); reset.setAccessible(true); reset.invoke(plugin);
		ready(); thread.tick(); assertTrue(messages.isEmpty());
		message("After shutdown", false); set("running", false);
		thread.tick(); assertTrue(messages.isEmpty());
		assertTrue(thread.pending.isEmpty());
	}

	@Test
	public void redMessagesUseTheSameGuardAndEscapePresetText() throws Exception
	{
		setup(); message("Skipped importing '<name>' because it already exists", true);
		thread.tick(); assertTrue(messages.isEmpty());
		ready(); thread.tick();
		assertEquals("<col=ff0000>World Filter Presets: Skipped importing '<lt>name<gt>' because it already exists</col>", messages.get(0));
	}

	private static final class DeferredThread extends ClientThread
	{
		final List<BooleanSupplier> pending = new ArrayList<>();
		@Override public void invokeLater(BooleanSupplier action) { pending.add(action); }
		void tick() { pending.removeIf(BooleanSupplier::getAsBoolean); }
	}
}

package com.kierenboal.worldfilterpresets;

import org.junit.Test;
import static org.junit.Assert.*;

public class PresetPromptsTest
{
	@Test
	public void callbackCanFollowChatboxCloseButOnlyRunOnce()
	{
		PresetPrompts prompts = new PresetPrompts();
		long ticket = prompts.begin();
		assertTrue(prompts.pending());
		prompts.close(ticket);
		assertFalse(prompts.pending());
		assertTrue(prompts.complete(ticket));
		assertFalse(prompts.complete(ticket));
	}

	@Test
	public void logoutProfileChangeAndShutdownInvalidateAnyPendingOperation()
	{
		for (String operation : new String[]{"name", "rename", "icon", "import", "delete", "bulk first", "bulk second"})
		{
			PresetPrompts prompts = new PresetPrompts();
			long old = prompts.begin();
			prompts.invalidate();
			assertFalse(operation, prompts.complete(old));
			assertFalse(prompts.pending());
		}
	}

	@Test
	public void cancelledOrOlderPromptCannotAffectNextPrompt()
	{
		PresetPrompts prompts = new PresetPrompts();
		long old = prompts.begin();
		prompts.close(old); // No callback is submitted by Escape/close.
		long current = prompts.begin();
		prompts.close(old);
		assertTrue(prompts.pending());
		assertFalse(prompts.complete(old));
		assertTrue(prompts.complete(current));
	}

	@Test
	public void bulkDeleteRequiresIndependentSecondTicketWithReversedButtons()
	{
		PresetRepository repository = new PresetRepository(PresetTestSupport.codec(), null, value -> { });
		repository.add("Keep until both confirmations", new int[11]);
		PresetPrompts prompts = new PresetPrompts();
		assertArrayEquals(new String[]{"Yes", "No"}, PresetPrompts.confirmationOptions(false));
		assertArrayEquals(new String[]{"No", "Yes"}, PresetPrompts.confirmationOptions(true));
		long first = prompts.begin();
		assertTrue(prompts.complete(first));
		long second = prompts.begin();
		assertEquals(1, repository.presets().size());
		assertFalse(prompts.complete(first));
		prompts.close(second); // Cancelling second stage never invokes deleteAll.
		assertEquals(1, repository.presets().size());
	}

	@Test
	public void unsavedDecisionSavesDiscardsOrCancelsTransition()
	{
		for (PresetDecision decision : PresetDecision.values())
		{
			StringBuilder calls = new StringBuilder();
			decision.apply(() -> calls.append("save "), () -> calls.append("switch"));
			assertEquals(decision == PresetDecision.SAVE ? "save switch" : decision == PresetDecision.DISCARD ? "switch" : "", calls.toString());
		}
	}
}

package com.kierenboal.worldfilterpresets;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class PresetRepositoryTest
{
	private final PresetCodec codec = PresetTestSupport.codec();
	private final List<String> writes = new ArrayList<>();
	private PresetRepository state() { return new PresetRepository(codec, null, writes::add); }

	@Test
	public void newProfileDelegatesToClientAndProtectsBuiltIns()
	{
		PresetRepository state = state();
		assertEquals(PresetRepository.CLIENT, state.selected());
		assertNull(state.working());
		assertEquals(0, writes.size());
		state.edit(new int[11]);
		assertNull(state.working());
		state.delete(PresetRepository.CLIENT);
		state.delete(PresetRepository.NONE);
		assertEquals(0, writes.size());
		assertTrue(state.presets().isEmpty());
		state.select(PresetRepository.NONE);
		assertArrayEquals(new int[11], state.working());
		state.deleteAll();
		assertEquals(PresetRepository.NONE, state.selected());
	}

	@Test
	public void builtInEditsBecomeUnsavedCustomWithoutModifyingDefaults()
	{
		PresetRepository state = state();
		state.select(PresetRepository.NONE);
		int[] values = new int[11]; values[1] = 4;
		int count = writes.size();
		state.edit(values);
		assertEquals(PresetRepository.CUSTOM, state.selected());
		assertEquals("Custom", state.selectedName());
		assertEquals(count, writes.size());
		state.select(PresetRepository.NONE);
		assertArrayEquals(new int[11], state.working());
	}

	@Test
	public void maintainsStableSelectionAcrossDeletionAndReload()
	{
		PresetRepository state = state();
		Preset first = state.add("First", new int[11]);
		Preset second = state.add("Second", new int[11]);
		state.delete(first.id);
		assertEquals(second.id, state.selected());
		PresetRepository loaded = new PresetRepository(codec, writes.get(writes.size() - 1), writes::add);
		assertEquals(second.id, loaded.selected());
		assertEquals("Second", loaded.selectedName());
		loaded.delete(second.id);
		assertEquals(PresetRepository.CLIENT, loaded.selected());
		assertNull(loaded.working());
	}

	@Test
	public void defaultsNamesUsingCustomCountAndAvoidsCollisions()
	{
		PresetRepository state = state();
		assertEquals("Preset 1", state.defaultName());
		Preset first = state.add("   ", new int[11]);
		assertEquals("Preset 1", first.name);
		assertEquals("Preset 2", state.defaultName());
		state.add("Preset 2", new int[11]);
		assertEquals(2, state.presets().size());
		state.delete(first.id);
		assertEquals("Preset 3", state.defaultName());
		assertEquals(80, PresetRepository.normalizeName("x".repeat(81), "Fallback").length());
	}

	@Test
	public void keepsSavedAndWorkingArraysIndependent()
	{
		PresetRepository state = state();
		int[] filters = new int[11];
		Preset preset = state.add("Saved", filters);
		filters[0] = 3;
		assertFalse(state.dirty());
		int[] working = state.working(); working[1] = 4;
		assertFalse(state.dirty());
		state.edit(working);
		assertTrue(state.dirty());
		assertEquals(0, preset.filters()[1]);
		state.update(preset.withFilters(state.working()));
		assertFalse(state.dirty());
		state.edit(new int[11]);
		assertTrue(state.dirty());
		state.select(preset.id);
		assertFalse(state.dirty());
		assertEquals(4, state.working()[1]);
	}

	@Test
	public void importsAppendWithFreshIdsAndPreserveSelectionAndEditsInOneWrite()
	{
		PresetRepository state = state();
		Preset preset = state.add("Duplicate", new int[11]);
		int[] changed = new int[11]; changed[2] = 7;
		state.edit(changed);
		int count = writes.size();
		Preset incoming = preset.withName("New one");
		Preset incoming2 = preset.withName("New two");
		state.applyImport(state.previewImport(java.util.Arrays.asList(incoming, incoming2)));
		assertEquals(count + 1, writes.size());
		assertEquals(preset.id, state.selected());
		assertArrayEquals(changed, state.working());
		assertTrue(state.dirty());
		assertEquals(3, state.presets().size());
		assertNotEquals(preset.id, state.presets().get(1).id);
		assertNotEquals(state.presets().get(1).id, state.presets().get(2).id);
		PresetRepository loaded = new PresetRepository(codec, writes.get(writes.size() - 1), writes::add);
		assertEquals(preset.id, loaded.selected());
		assertFalse(loaded.dirty());
	}

	@Test
	public void deletesAllCustomPresetsInOneWriteAndReturnsActiveCustomToClient()
	{
		PresetRepository state = state();
		state.add("One", new int[11]); state.add("Two", new int[11]);
		int count = writes.size();
		state.deleteAll();
		assertEquals(count + 1, writes.size());
		assertTrue(state.presets().isEmpty());
		assertEquals(PresetRepository.CLIENT, state.selected());
		assertNull(state.working());
	}

	@Test
	public void hasNoFiveSlotLimitAndFallsBackFromMissingSelection()
	{
		PresetRepository state = state();
		Preset preset = state.add("Many", new int[11]);
		List<Preset> incoming = new ArrayList<>();
		for (int i = 0; i < 500; i++) { incoming.add(preset.withName("Imported " + i)); }
		state.applyImport(state.previewImport(incoming));
		assertEquals(501, state.presets().size());
		state.select("missing");
		assertEquals(PresetRepository.CLIENT, state.selected());
		assertNull(state.working());
	}

	@Test
	public void enforcesUniqueNamesAndReservedNamesWithoutMutatingState()
	{
		PresetRepository state = state();
		Preset first = state.add("Aussie worlds", new int[11]);
		Preset other = state.add("Other", new int[11]);
		for (String name : new String[]{" AUSSIE WORLDS ", "In-game filter", "NO FILTERS"})
		{
			int count = writes.size();
			try { state.add(name, new int[11]); fail(name); }
			catch (IllegalArgumentException expected) { assertEquals(2, state.presets().size()); }
			try { state.update(other.withName(name)); fail(name); }
			catch (IllegalArgumentException expected) { assertEquals("Other", state.find(other.id).name); }
			assertEquals(count, writes.size());
		}
		state.update(first.withName("AUSSIE WORLDS"));
		assertEquals("AUSSIE WORLDS", state.find(first.id).name);
	}

	@Test
	public void persistsSharedOrderAndIndependentCogVisibilityForBuiltInsAndCustoms()
	{
		PresetRepository state = state();
		Preset a = state.add("A", new int[11]);
		Preset b = state.add("B", new int[11]);
		state.move(a.id, -1, false, false);
		state.move(PresetRepository.CLIENT, 1, false, false);
		assertEquals(java.util.Arrays.asList(a.id, PresetRepository.CLIENT, PresetRepository.NONE, b.id), state.visibleEntries(false, false));
		state.toggleCog(PresetRepository.NONE);
		state.toggleCog(a.id);
		assertEquals(java.util.Arrays.asList(PresetRepository.CLIENT, b.id), state.cogEntries());
		assertEquals(java.util.Arrays.asList(a.id, b.id), state.visibleEntries(true, true));
		PresetRepository loaded = new PresetRepository(codec, writes.get(writes.size() - 1), writes::add);
		assertEquals(state.visibleEntries(false, false), loaded.visibleEntries(false, false));
		assertEquals(state.cogEntries(), loaded.cogEntries());
		assertEquals("In-game filter", loaded.name(PresetRepository.CLIENT));
	}

	@Test
	public void movementSkipsHiddenEntriesAndKeepsTheirPositions()
	{
		PresetRepository state = state();
		Preset a = state.add("A", new int[11]);
		state.move(a.id, -1, false, true);
		assertEquals(java.util.Arrays.asList(a.id, PresetRepository.NONE, PresetRepository.CLIENT), state.visibleEntries(false, false));
		assertFalse(state.canMove(a.id, -1, false, true));
		assertFalse(state.canMove(PresetRepository.CLIENT, 1, false, true));
		assertFalse(state.canMove(PresetRepository.NONE, 1, false, true));
	}

	@Test
	public void importsPreviewSkipsIdenticalAndOverwritesChangedNamesKeepingPositionAndSelection()
	{
		PresetRepository state = state();
		Preset a = state.add("A", new int[11]);
		Preset b = state.add("B", new int[11]);
		state.move(b.id, -1, false, false);
		state.select(a.id);
		int[] unsaved = new int[11]; unsaved[0] = 1; state.edit(unsaved);
		int[] replacement = new int[11]; replacement[1] = 4;
		Preset incoming = a.withName("a").withFilters(replacement).withCogVisibility(false);
		List<String> order = state.visibleEntries(false, false);
		int count = writes.size();
		PresetRepository.ImportPlan preview = state.previewImport(java.util.Arrays.asList(b, incoming, a.withName("New")));
		assertEquals(1, preview.additions.size());
		assertEquals(1, preview.overwrites.size());
		assertEquals(1, preview.skipped.size());
		assertEquals(count, writes.size()); // Merely previewing (or cancelling) changes nothing.
		assertArrayEquals(unsaved, state.working());
		assertTrue(preview.overwrites(a.id));
		state.applyImport(preview);
		assertEquals(count + 1, writes.size());
		assertEquals(a.id, state.selected());
		assertEquals("a", state.find(a.id).name);
		assertFalse(state.showInCogMenu(a.id));
		assertArrayEquals(replacement, state.working());
		assertFalse(state.dirty());
		assertEquals(order, state.visibleEntries(false, false).subList(0, order.size()));
	}

	@Test
	public void allIdenticalImportsDoNotWriteAndStalePlansCannotApply()
	{
		PresetRepository state = state();
		Preset a = state.add("A", new int[11]);
		int count = writes.size();
		PresetRepository.ImportPlan skip = state.previewImport(Collections.singletonList(a));
		assertFalse(skip.hasChanges());
		state.applyImport(skip);
		assertEquals(count, writes.size());
		PresetRepository.ImportPlan plan = state.previewImport(Collections.singletonList(a.withIcon(42)));
		int[] working = new int[11]; working[2] = 4; state.edit(working);
		try { state.applyImport(plan); fail(); }
		catch (IllegalArgumentException expected) { assertEquals(-1, state.find(a.id).icon); }
	}

	@Test
	public void exportUsesRelativeCustomOrderWithoutBuiltInsOrPositions()
	{
		PresetRepository state = state();
		Preset a = state.add("A", new int[11]);
		Preset b = state.add("B", new int[11]);
		state.move(b.id, -1, false, false);
		List<Preset> bulk = codec.importPresets(codec.export(state.presets()));
		assertEquals("B", bulk.get(0).name);
		assertEquals("A", bulk.get(1).name);
		String single = codec.export(Collections.singletonList(a));
		assertFalse(single.contains("order"));
		PresetRepository target = new PresetRepository(codec, null, value -> { });
		target.applyImport(target.previewImport(codec.importPresets(single)));
		assertEquals("A", target.presets().get(0).name);
	}
}

